import { CHAIN } from './chain-config.js';
import { sharedReadProvider } from './read-provider.js';

// Ethereum Sepolia currently clears with a 1-wei tip. Leaving these fields
// absent lets the wallet choose a much larger default on high-gas game calls.
// Read the live base fee; never carry a fixed gas price across blocks/networks.
export async function sepoliaFeeOverrides({ chainId = CHAIN.id, provider } = {}) {
  if (Number(chainId) !== 11155111) return {};
  try {
    const block = await (provider ?? sharedReadProvider()).getBlock('latest');
    if (block?.baseFeePerGas == null) throw new Error('Missing base fee');
    const baseFee = BigInt(block.baseFeePerGas);
    if (baseFee < 0n) throw new Error('Invalid base fee');
    return { maxPriorityFeePerGas: 1n, maxFeePerGas: baseFee * 2n + 1n };
  } catch (cause) {
    throw new Error('Could not read Sepolia gas fees. Please retry.', { cause });
  }
}

/** Preserve deliberate caller overrides; otherwise attach the testnet policy. */
export async function withTransactionFees(request, options) {
  if (request?.gasPrice != null || request?.maxFeePerGas != null || request?.maxPriorityFeePerGas != null) {
    return request;
  }
  return { ...request, ...await sepoliaFeeOverrides(options) };
}

/** Affordability checks must use the same fee policy as the eventual send. */
export async function transactionFeeData(provider) {
  if (Number(CHAIN.id) === 11155111) return sepoliaFeeOverrides();
  return typeof provider?.getFeeData === 'function' ? provider.getFeeData() : null;
}
